+const (
+	standaloneProblem20Item    = "bb13338f-045e-4853-8cc4-90ec80dc8b4f"
+	standaloneProblem20Request = "ee87cf09b602ba3eec64112ecf8e85bbf1d539864308a2ab542ac467a9202cb4"
+)
+
+// standaloneReconstructionFixture is a one-commit checkout with the evidence file that
+// the documented reconstruct mode accepts for Problem20.
+type standaloneReconstructionFixture struct {
+	binary, checkout, evidence, archive string
+}
+
+func newStandaloneReconstructionFixture(t *testing.T) standaloneReconstructionFixture {
+	t.Helper()
+	dir := t.TempDir()
+	f := standaloneReconstructionFixture{
+		binary:   filepath.Join(dir, "kogen-build"),
+		checkout: filepath.Join(dir, "checkout"),
+		evidence: filepath.Join(dir, "evidence.json"),
+		archive:  filepath.Join(dir, "archive"),
+	}
+	if out, err := exec.Command("go", "build", "-o", f.binary, ".").CombinedOutput(); err != nil {
+		t.Fatalf("build: %v: %s", err, out)
+	}
+	if err := os.Mkdir(f.checkout, 0o700); err != nil {
+		t.Fatal(err)
+	}
+	gitOut := func(args ...string) string {
+		t.Helper()
+		out, err := exec.Command("git", append([]string{"-C", f.checkout, "-c", "user.name=t", "-c", "user.email=t@example.invalid"}, args...)...).CombinedOutput()
+		if err != nil {
+			t.Fatalf("git %v: %v: %s", args, err, out)
+		}
+		return strings.TrimSpace(string(out))
+	}
+	gitOut("init", "-q")
+	gitOut("commit", "-q", "--allow-empty", "-m", "baseline")
+	builds := []any{}
+	for i, id := range []string{"b97d96270b9f4801aa09a7ba00e64f84", "c3b576c985bb4299b1b443666eed172a"} {
+		receipt := filepath.Join(dir, id+".json")
+		body := []byte(fmt.Sprintf("{\"receipt\":%d}\n", i+1))
+		if err := os.WriteFile(receipt, body, 0o600); err != nil {
+			t.Fatal(err)
+		}
+		sum := sha256.Sum256(body)
+		builds = append(builds, map[string]any{
+			"id": id, "receipt_sha256": strings.Repeat("a", 63) + string(rune('0'+i)),
+			"candidate_tree": strings.Repeat("b", 39) + string(rune('0'+i)),
+			"path":           receipt, "copy_sha256": hex.EncodeToString(sum[:]),
+		})
+	}
+	evidence := map[string]any{
+		"queue_item": map[string]any{"id": standaloneProblem20Item, "version": 18}, "obligation": "Problem20", "owner": "fleet",
+		"request":         map[string]any{"document": "queue-request-" + standaloneProblem20Item, "revision": 3, "sha256": standaloneProblem20Request},
+		"current_request": map[string]any{"revision": 3, "sha256": standaloneProblem20Request},
+		"baseline":        map[string]any{"head": gitOut("rev-parse", "HEAD")},
+		"prior":           map[string]any{"attempts": []any{"577e7c601aab41a39eb0820fc5fee5fb"}, "builds": builds, "spend": map[string]any{"units": 42}},
+		"effects":         map[string]any{"publication": "none", "external": "none"},
+		"owners":          []any{}, "custody": map[string]any{"generation": "gen-1", "revoked": true}, "claims": map[string]any{},
+	}
+	raw, err := json.Marshal(evidence)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(f.evidence, raw, 0o600); err != nil {
+		t.Fatal(err)
+	}
+	return f
+}
+
+// snapshot describes every path of the checkout outside .git, with file contents, so
+// that any write into the checkout changes it.
+func (f standaloneReconstructionFixture) snapshot(t *testing.T) string {
+	t.Helper()
+	var lines []string
+	err := filepath.WalkDir(f.checkout, func(path string, d os.DirEntry, err error) error {
+		if err != nil {
+			return err
+		}
+		rel, _ := filepath.Rel(f.checkout, path)
+		if rel == ".git" {
+			return filepath.SkipDir
+		}
+		if d.IsDir() {
+			lines = append(lines, "dir "+rel)
+			return nil
+		}
+		body, err := os.ReadFile(path)
+		if err != nil {
+			return err
+		}
+		lines = append(lines, fmt.Sprintf("file %s %x", rel, sha256.Sum256(body)))
+		return nil
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	return strings.Join(lines, "\n")
+}
+
+// run starts the built command and returns its process exit status, its stdout decoded as
+// the JSON envelope and as a generic object, and its stderr.
+func (f standaloneReconstructionFixture) run(t *testing.T, args ...string) (int, result, map[string]any, string) {
+	t.Helper()
+	var stdout, stderr strings.Builder
+	cmd := exec.Command(f.binary, args...)
+	cmd.Stdout, cmd.Stderr = &stdout, &stderr
+	exit := 0
+	if err := cmd.Run(); err != nil {
+		e, ok := err.(*exec.ExitError)
+		if !ok {
+			t.Fatalf("run %v: %v", args, err)
+		}
+		exit = e.ExitCode()
+	}
+	var r result
+	var generic map[string]any
+	if err := json.Unmarshal([]byte(stdout.String()), &r); err != nil {
+		t.Fatalf("stdout is not the JSON envelope: %v: %q (stderr %q)", err, stdout.String(), stderr.String())
+	}
+	if err := json.Unmarshal([]byte(stdout.String()), &generic); err != nil {
+		t.Fatalf("stdout is not a JSON object: %v: %q", err, stdout.String())
+	}
+	return exit, r, generic, stderr.String()
+}
+
+func TestStandaloneReconstructionReadbackOfAnUnrecordedItemIsAbsent(t *testing.T) {
+	f := newStandaloneReconstructionFixture(t)
+	before := f.snapshot(t)
+	exit, r, generic, stderr := f.run(t, "reconstruction", "--project", f.checkout, "--item", standaloneProblem20Item)
+	if exit != 1 || r.ExitCode != 1 {
+		t.Fatalf("exit status %d, exit_code %d, want 1 and 1 (stderr %q)", exit, r.ExitCode, stderr)
+	}
+	if r.Reconstruction == nil || r.Reconstruction.State != "absent" || len(r.Reconstruction.Attempts) != 0 || len(r.Reconstruction.Wakes) != 0 {
+		t.Fatalf("reconstruction: %+v", r.Reconstruction)
+	}
+	if r.Error == nil {
+		t.Fatal("an absent readback has a null error")
+	}
+	rec, ok := generic["reconstruction"].(map[string]any)
+	if !ok || len(rec) != 3 || rec["state"] != "absent" || rec["attempts"] == nil || rec["wakes"] == nil {
+		t.Fatalf("an absent readback has only state, attempts and wakes: %v", generic["reconstruction"])
+	}
+	if after := f.snapshot(t); after != before {
+		t.Fatalf("the readback wrote into the checkout:\n%s\n--- after ---\n%s", before, after)
+	}
+}
+
+func TestStandaloneReconstructStopAfterPreservedIsInterruptedWithoutAttempt(t *testing.T) {
+	f := newStandaloneReconstructionFixture(t)
+	exit, r, generic, stderr := f.run(t, "reconstruct", "--project", f.checkout, "--evidence", f.evidence, "--archive", f.archive, "--stop-after", "preserved")
+	if exit != 1 || r.ExitCode != 1 {
+		t.Fatalf("exit status %d, exit_code %d, want 1 and 1 (stderr %q)", exit, r.ExitCode, stderr)
+	}
+	if r.Error == nil {
+		t.Fatal("an interrupted run has a null error")
+	}
+	rec, ok := generic["reconstruction"].(map[string]any)
+	if !ok || rec["state"] != "interrupted" {
+		t.Fatalf("reconstruction state: %v", generic["reconstruction"])
+	}
+	for _, key := range []string{"attempts", "wakes"} {
+		if list, ok := rec[key].([]any); !ok || len(list) != 0 {
+			t.Fatalf("an interrupted run has %s %v, want an empty array", key, rec[key])
+		}
+	}
+	if r.Reconstruction == nil || r.Reconstruction.State != "interrupted" || r.Reconstruction.Archive != f.archive {
+		t.Fatalf("reconstruction: %+v", r.Reconstruction)
+	}
+	if _, err := os.Stat(filepath.Join(f.archive, "manifest.json")); err != nil {
+		t.Fatalf("the preserved archive has no manifest: %v", err)
+	}
+}
+
+func TestStandaloneReconstructRefusesAnInvalidStopAfter(t *testing.T) {
+	f := newStandaloneReconstructionFixture(t)
+	before := f.snapshot(t)
+	exit, r, _, _ := f.run(t, "reconstruct", "--project", f.checkout, "--evidence", f.evidence, "--archive", f.archive, "--stop-after", "created")
+	if exit != 2 || r.ExitCode != 2 {
+		t.Fatalf("exit status %d, exit_code %d, want 2 and 2", exit, r.ExitCode)
+	}
+	if r.Error == nil || r.Error.Category != "usage" || r.Error.Kind != "invalid_arguments" || !strings.Contains(r.Error.Message, "--stop-after") || !strings.Contains(r.Error.Message, `"created"`) {
+		t.Fatalf("error: %+v", r.Error)
+	}
+	if r.Reconstruction != nil {
+		t.Fatalf("a usage refusal carries a reconstruction: %+v", r.Reconstruction)
+	}
+	if _, err := os.Stat(f.archive); !os.IsNotExist(err) {
+		t.Fatalf("the refused run created the archive: %v", err)
+	}
+	if after := f.snapshot(t); after != before {
+		t.Fatalf("the refused run wrote into the checkout:\n%s\n--- after ---\n%s", before, after)
+	}
+}

